def pin(b):return {"bytes":len(b),"sha256":hashlib.sha256(b).hexdigest(),"git_blob":hashlib.sha1(b"blob "+str(len(b)).encode()+b"\0"+b).hexdigest()}
assert pin(payload["receive.py"].encode())["git_blob"]=="6498e78571eefb181720758e9e06c961f5f5468b"
assert pin(payload["CONTRACT.md"].encode())["git_blob"]=="2012387eec7356f3035e85fd06d370ed163a7cc3"
vm=subprocess.run(["/usr/bin/vm_stat"],capture_output=True,text=True,check=True,timeout=5)
page=int(re.search(r"page size of (\d+) bytes",vm.stdout).group(1))
memory=page*sum(int(re.search(r"^"+re.escape(k)+r":\s+(\d+)",vm.stdout,re.M).group(1)) for k in ("Pages free","Pages inactive","Pages speculative"))
disk=shutil.disk_usage(stage).free
author_bytes=sum(p.stat().st_size for parent in (stage,target) for p in parent.rglob("*") if p.is_file())
admission={"utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"free_disk":disk,"conservative_memory":memory,"author_and_install_bytes":author_bytes,"receiver_cap":512*1024,"disk_floor":256*1024**2,"memory_floor":2*1024**3,"pid":os.getpid()}
assert disk>=256*1024**2 and memory>=2*1024**3 and author_bytes<=4*1024**2,admission
assert not os.path.lexists(root),"refuse existing receiver root"
os.umask(0o077);root.mkdir(mode=0o700)
files={}
for name,text in payload.items():
 p=root/name;p.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
 b=text.encode()
 with p.open("xb") as f:f.write(b)
 assert p.read_bytes()==b
 files[name]=pin(b)
